// 당일 메인 화면
import { useState, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { formatDisplayDate, parseDate, getNextDay, getPrevDay, formatDate, getTodayString } from '../utils/date';
import { useScheduleStore } from '../hooks/useScheduleStore';
import { useProjectTodos } from '../hooks/useWorkStore';
import Timeline from '../components/Timeline';
import TodoList from '../components/TodoList';
import EventModal from '../components/EventModal';
import type { ScheduleEvent } from '../types';
import '../styles/DailyPage.css';

export default function DailyPage() {
  const { date } = useParams<{ date: string }>();
  const navigate = useNavigate();
  
  const currentDate = date ? parseDate(date) : new Date();
  const dateString = date || getTodayString();

  const {
    events,
    todos,
    createEvent,
    updateEvent,
    deleteEvent,
    createRecurring,
    createTodo,
    updateTodo,
    deleteTodo,
  } = useScheduleStore(dateString);

  // 작업 todo 가져오기 (달력에 표시할 것만)
  const { todos: workTodos, doneTodos: workDoneTodos, updateTodo: updateWorkTodo, deleteTodo: deleteWorkTodo } = useProjectTodos();

  // 당일에 해당하는 작업 투두 필터링
  // - show_in_calendar가 true이고
  // - 시작일~종료일 기간 내에 해당하거나, 마감일 이전이면 표시
  // - 완료/취소 상태여도 상태를 표시하여 유지
  const todayWorkTodos = useMemo(() => {
    const allWorkTodos = [...workTodos, ...workDoneTodos];
    const currentDateObj = new Date(dateString);
    
    return allWorkTodos.filter(todo => {
      // 달력 표시 옵션이 꺼져 있으면 제외
      if (!todo.show_in_calendar) return false;
      
      // 시작일과 종료일 (또는 마감일) 확인
      const startDate = todo.start_at ? new Date(todo.start_at.split('T')[0]) : null;
      const endDate = todo.end_at 
        ? new Date(todo.end_at.split('T')[0]) 
        : (todo.due_at ? new Date(todo.due_at.split('T')[0]) : null);
      
      // 날짜가 없으면 제외
      if (!startDate && !endDate) return false;
      
      // 시작일만 있는 경우: 시작일 이후면 표시
      if (startDate && !endDate) {
        return currentDateObj >= startDate;
      }
      
      // 종료일/마감일만 있는 경우: 마감일 이전이면 표시
      if (!startDate && endDate) {
        return currentDateObj <= endDate;
      }
      
      // 둘 다 있는 경우: 기간 내에 있으면 표시
      return currentDateObj >= startDate! && currentDateObj <= endDate!;
    }).map(todo => ({
      id: todo.id,
      content: todo.content,
      is_done: todo.is_done,
      status: todo.status || (todo.is_done ? 'done' : 'active'),
    }));
  }, [workTodos, workDoneTodos, dateString]);

  // 작업 todo 상태 변경
  const handleWorkTodoStatusChange = async (todoId: string, status: string) => {
    const todo = [...workTodos, ...workDoneTodos].find(t => t.id === todoId);
    if (todo) {
      await updateWorkTodo({
        ...todo,
        status: status as 'active' | 'done' | 'delayed' | 'cancelled',
        is_done: status === 'done',
        completed_at: status === 'done' ? Date.now() : null,
      });
    }
  };

  // 작업 todo 삭제
  const handleWorkTodoDelete = async (todoId: string) => {
    if (confirm('작업에서도 이 To do가 삭제됩니다. 정말 삭제하시겠습니까?')) {
      await deleteWorkTodo(todoId);
    }
  };

  const [selectedEvent, setSelectedEvent] = useState<ScheduleEvent | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isNewEvent, setIsNewEvent] = useState(false); // 새 이벤트인지 여부

  const handlePrevDay = () => {
    navigate(`/daily/${formatDate(getPrevDay(currentDate))}`);
  };

  const handleNextDay = () => {
    navigate(`/daily/${formatDate(getNextDay(currentDate))}`);
  };

  const handleToday = () => {
    navigate(`/daily/${getTodayString()}`);
  };

  const handleGoToMonthly = () => {
    navigate(`/monthly/${formatDate(currentDate).slice(0, 7)}`);
  };

  // 새 이벤트 생성 시 (타임라인 드래그)
  const handleEventCreate = (event: ScheduleEvent) => {
    // DB에 저장하지 않고 모달만 열기
    setSelectedEvent(event);
    setIsNewEvent(true);
    setIsModalOpen(true);
  };

  // 기존 이벤트 클릭 시
  const handleEventClick = (event: ScheduleEvent) => {
    setSelectedEvent(event);
    setIsNewEvent(false);
    setIsModalOpen(true);
  };

  const handleModalClose = () => {
    setIsModalOpen(false);
    setSelectedEvent(null);
    setIsNewEvent(false);
  };

  // 모달에서 저장 시
  const handleEventSave = (event: ScheduleEvent) => {
    console.log('handleEventSave called, isNewEvent:', isNewEvent, 'event:', event);
    if (isNewEvent) {
      // 새 이벤트는 createEvent로 저장
      console.log('Calling createEvent');
      createEvent(event);
    } else {
      // 기존 이벤트는 updateEvent로 업데이트
      console.log('Calling updateEvent');
      updateEvent(event);
    }
  };

  return (
    <div className="daily-page">
      {/* 상단 헤더 */}
      <header className="daily-header">
        <div className="header-left">
          <button className="today-btn" onClick={handleToday}>오늘</button>
          <button className="work-btn" onClick={() => navigate('/work')}>작업</button>
          <button 
            className="search-btn" 
            onClick={() => window.dispatchEvent(new Event('open-search'))}
            title="검색 (Ctrl+K)"
          >
            🔍
          </button>
        </div>
        <div className="date-nav">
          <button className="nav-btn" onClick={handlePrevDay}>◀</button>
          <h1 className="current-date" onClick={handleGoToMonthly}>{formatDisplayDate(currentDate)}</h1>
          <button className="nav-btn" onClick={handleNextDay}>▶</button>
        </div>
        <div className="header-right"></div>
      </header>

      {/* 메인 컨텐츠 */}
      <main className="daily-content">
        {/* 타임라인 */}
        <section className="timeline-section">
          {/* To-do 빠른 입력 */}
          <div className="quick-todo">
            <TodoList
              todos={todos}
              onTodoCreate={createTodo}
              onTodoUpdate={updateTodo}
              onTodoDelete={deleteTodo}
              workTodos={todayWorkTodos}
              onWorkTodoStatusChange={handleWorkTodoStatusChange}
              onWorkTodoDelete={handleWorkTodoDelete}
            />
          </div>
          
          <div className="timeline-wrapper">
            <Timeline
              date={dateString}
              events={isNewEvent && selectedEvent ? [...events, selectedEvent] : events}
              onEventCreate={handleEventCreate}
              onEventUpdate={updateEvent}
              onEventDelete={deleteEvent}
              onEventClick={handleEventClick}
            />
          </div>
        </section>
      </main>

      {/* 일정 편집 모달 */}
      <EventModal
        event={selectedEvent}
        isOpen={isModalOpen}
        onClose={handleModalClose}
        onSave={handleEventSave}
        onDelete={deleteEvent}
        onCreateRecurring={createRecurring}
      />
    </div>
  );
}
